        "+            elif os.environ.get(env_var):",
        "+                console.print(f"  [green]✓[/green] {name}: Configured")",
        "+            else:",
        "+                console.print(f"  [red]✗[/red] {name}: Not configured ({env_var})")",
        "+    ",
        "+    if show_all or cache:",
